public class GJChronology_hashCode_TriageGen1Test {



    @Test
    public void testHashCodeDifferentInstancesSameParameters() {
        DateTimeZone zone = DateTimeZone.UTC;
        long cutover = 123456789L;
        int minDays = 4;

        GJChronology chronology1 = GJChronology.getInstance(zone, cutover, minDays);
